using UnityEngine;
using RoguePrince.CheatMenu;
int passed=0,failed=0;
void Check(bool b,string reason){if(!b)throw new Exception(reason);}
void Test(string name,Action body){GUI.Reset();try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
Test("word-wrapped affix text never calls stripped scroll methods",()=>{new MenuController().Draw(Vector2.zero);Check(GUI.Unsupported==0&&GUI.Begins==1&&GUI.Ends==1&&GUI.Labels==1,"native clipping must replace unavailable scroll widgets");});
Test("scroll wheel moves text inside clipping viewport",()=>{Event.current=new(){type=EventType.ScrollWheel,mousePosition=new(10,10),delta=new(0,2)};var p=new MenuController().Draw(Vector2.zero);Check(p.y>0&&GUI.Offset.y==-p.y&&Event.current.type==EventType.Used,"wheel was not routed to text viewport");});
Test("wheel outside viewport leaves scroll and game event untouched",()=>{Event.current=new(){type=EventType.ScrollWheel,mousePosition=new(150,80),delta=new(0,2)};var p=new MenuController().Draw(new(0,20));Check(p.y==20&&Event.current.type==EventType.ScrollWheel,"outside wheel captured");});
Test("shrinking text clamps stale scroll back to top",()=>{var m=new MenuController();m.ContentHeight(30);var p=m.Draw(new(0,999));Check(p.y==0,"stale offset hides short affix list");});
Test("drawing failure always pops its native clip",()=>{GUI.FailLabel=true;try{new MenuController().Draw(Vector2.zero);throw new Exception("expected label failure");}catch(InvalidOperationException){}Check(GUI.Depth==0&&GUI.Begins==GUI.Ends,"native clip leaked after label failure");});
Test("draw failure releases input pause cursor and returns to safe page",()=>{var m=new MenuController();var game=new GameSession();var ui=new UnityEngine.EventSystems.EventSystem();UnityEngine.Object.Systems=new[]{ui};Time.timeScale=.75f;Cursor.visible=false;Cursor.lockState=CursorLockMode.Locked;m.Arm(game);Check(Time.timeScale==0&&!ui.enabled&&!game.Player.Input._isListeningUnityInput,"fixture did not acquire actual production InputLease");m.Recover();Check(m.Clean,"hidden menu retained failed tab or capture state");Check(Time.timeScale==.75f&&ui.enabled&&game.Player.Input._isListeningUnityInput&&Cursor.lockState==CursorLockMode.Locked&&!Cursor.visible,"owned pause/UI/player/cursor was not returned");m.Recover();Check(Time.timeScale==.75f&&ui.enabled,"recovery not idempotent");});
Test("thumb drag reaches bottom and releases outside the viewport",()=>{var m=new MenuController();Event.current=new(){type=EventType.MouseDown,button=0,mousePosition=new(90,30)};var p=m.Draw(Vector2.zero);Check(p.y>0,"thumb not captured");Event.current=new(){type=EventType.MouseDrag,mousePosition=new(90,200)};p=m.Draw(p);Check(p.y==240,"drag exceeded content range");Event.current=new(){type=EventType.MouseUp,button=0,mousePosition=new(150,200)};m.Draw(p);Check(Event.current.type==EventType.Used&&GUI.Depth==0,"outside release leaked capture or clip");});
Test("compact scale keeps clipping coordinates and thumb within the pane",()=>{var m=new MenuController();m.Scale(.45f);Event.current=new(){type=EventType.ScrollWheel,mousePosition=new(20,10),delta=new(0,999)};var p=m.Draw(Vector2.zero);Check(Math.Abs(GUI.ClipRect.width-45)<.01f&&Math.Abs(GUI.ClipRect.height-27)<.01f&&p.y==273,"scaled viewport or scroll range incorrect");});
Test("label failure restores wrapping before next page draws",()=>{var m=new MenuController();GUI.FailLabel=true;try{m.Draw(Vector2.zero);}catch(InvalidOperationException){}Check(!m.Wrap&&GUI.Depth==0,"failed drawing left shared GUI style or clip changed");});
Test("recovery preserves external pause and initially disabled listeners",()=>{var m=new MenuController();var game=new GameSession();game.Player.Input._isListeningUnityInput=false;var disabled=new UnityEngine.EventSystems.EventSystem{enabled=false};var active=new UnityEngine.EventSystems.EventSystem();UnityEngine.Object.Systems=new[]{disabled,active};Time.timeScale=0;m.Arm(game);m.Recover();Check(Time.timeScale==0&&!disabled.enabled&&active.enabled&&!game.Player.Input._isListeningUnityInput,"recovery acquired ownership of someone else's pause or input");});
Console.WriteLine($"RESULT {passed} passed, {failed} failed");Environment.ExitCode=failed==0?0:1;
